// Define a data structure to hold the broadcasted Cartesian product.
#[derive(Debug, Clone)]
pub struct BroadcastObject {
    // shape.0 is the length of the first array (rows),
    // shape.1 is the length of the second array (columns).
    shape: (usize, usize),
    // flattened row-major data: for each i in 0..shape.0 and j in 0..shape.1,
    // the element at (i, j) is stored at index i * shape.1 + j.
    data: Vec<(f32, f32)>,
}

impl BroadcastObject {
    // Constructor: consumes the two input vectors and builds the Cartesian product.
    pub fn new(x: Vec<f32>, y: Vec<f32>) -> Self {
        let m = x.len();
        let n = y.len();
        // Pre-allocate exactly m * n elements.
        let mut data = Vec::with_capacity(m * n);
        for xi in &x {
            for yi in &y {
                data.push((*xi, *yi));
            }
        }
        BroadcastObject {
            shape: (m, n),
            data,
        }
    }

    // Returns the shape (rows, columns).
    pub fn shape(&self) -> (usize, usize) {
        self.shape
    }

    // Accessor: returns Some((x_i, y_j)) if (i,j) is in-bounds, otherwise None.
    pub fn get(&self, i: usize, j: usize) -> Option<(f32, f32)> {
        let (m, n) = self.shape;
        if i < m && j < n {
            // row-major indexing
            let idx = i * n + j;
            Some(self.data[idx])
        } else {
            None
        }
    }
}

// The required function signature.
pub fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject {
    BroadcastObject::new(x, y)
}

